"""New controlled development cases; labels describe stated deterministic predicates, not law."""
from pathlib import Path
import json,hashlib
BASE=Path(__file__).resolve().parent
def build():
    target=BASE/'new_cases.json'
    if target.exists():raise FileExistsError('Do not overwrite authored evaluation inputs')
    cases=[]
    def add(name,text,conflict,construction,category=None,provisional=False):
        cases.append(dict(case_id=name,text=text,confirmed_conflict_gold=conflict,
            expected_category=category,construction_rule=construction,
            provenance='PROVISIONAL_INTERPRETATION' if provisional else 'NEW_MECHANICAL_SYNTHETIC',
            independently_adjudicated=False,split='EXPOSED_DEVELOPMENT'))
    def sections(*texts):return '\n\n'.join(f'Section {i+1}. Timing\n{t}' for i,t in enumerate(texts))
    add('N01',sections('The Effective Date is 2026-01-01.','The Expiration Date is 2026-12-31.'),False,'Ordered explicit term endpoints')
    add('N02',sections('The Effective Date is 2026-12-31.','The Expiration Date is 2026-01-01.'),True,'Reversed explicit term endpoints')
    add('N03',sections('For Agreement A, the Effective Date is 2026-06-01.','For Agreement A, the Expiration Date is 2026-12-31.','For Agreement B, the Effective Date is 2026-01-01.','For Agreement B, the Expiration Date is 2026-03-01.'),False,'Two individually valid agreements; no cross-product comparison')
    add('N04',sections('Buyer shall pay Invoice Alpha on 2026-02-01.','Seller shall pay Invoice Alpha on 2026-03-01.'),False,'Different explicit actors; no identical-obligation contradiction')
    add('N05',sections('Event Completion occurs on 2026-06-01.','Event Completion occurs on 2026-07-01.'),True,'Same unqualified exact named event, same scope, different singleton dates')
    add('N06',sections('Event Completion occurs on 2026-06-01.','Event Completion occurs on 2026-06-01.'),False,'Identical named-event date repeated')
    add('N07',sections('Event Completion occurs on 2026-06-01.','Event Inspection occurs on 2026-07-01.'),False,'Different named events need not share dates')
    add('N08',sections('Event Completion occurs on 2026-06-01.','Under the amendment, Event Completion occurs on 2026-07-01.'),None,'Amendment precedence requires interpretation',provisional=True)
    anchor='Invoice Alpha is received on 2026-01-01.'
    relative='Buyer shall pay Invoice Alpha within 30 calendar days after receipt of Invoice Alpha.'
    add('N09',sections(anchor,relative,'Buyer shall pay Invoice Alpha on 2026-01-20.'),False,'Explicit payment date within 30 calendar days after dated named receipt')
    add('N10',sections(anchor,relative,'Buyer shall pay Invoice Alpha on 2026-02-15.'),True,'Explicit payment date exceeds Jan 31 upper bound')
    add('N11',sections('Delivery Alpha occurs on 2026-01-01.','Buyer shall pay Invoice Alpha within 10 calendar days after Delivery Alpha.','Buyer shall pay Invoice Alpha on 2026-01-20.'),True,'Trigger and payment stated across sections; payment exceeds Jan 11')
    add('N12',sections(anchor,'Delivery Alpha occurs on 2026-01-15.',relative,'Buyer shall pay Invoice Alpha within 30 calendar days after Delivery Alpha.'),False,'Different trigger events cannot automatically form disjoint bounds')
    add('N13',sections(anchor,'Buyer shall give notice within 10 calendar days after receipt of Invoice Alpha.','Buyer shall give notice within 20 calendar days after receipt of Invoice Alpha.'),False,'Two upper bounds overlap; stricter deadline can satisfy both','POTENTIAL_INCONSISTENCY')
    add('N14',sections(anchor,'Buyer shall pay Invoice Alpha exactly 10 calendar days after receipt of Invoice Alpha.','Buyer shall pay Invoice Alpha exactly 20 calendar days after receipt of Invoice Alpha.'),True,'Disjoint singleton offsets for identical actor/action/trigger')
    add('N15',sections(anchor,relative,'Buyer shall pay Invoice Alpha at least 60 calendar days after receipt of Invoice Alpha.'),True,'Offset lower 60 exceeds upper 30')
    add('N16',sections(anchor,relative,'Buyer shall pay Invoice Alpha at least 10 calendar days after receipt of Invoice Alpha.'),False,'Offset interval [10,30] is feasible; no mathematical contradiction')
    add('N17',sections(anchor,relative,'Buyer shall pay Invoice Alpha within 30 business days after receipt of Invoice Alpha.'),False,'Business and calendar basis not interchangeable')
    add('N18',sections('Buyer shall pay Invoice Alpha within 30 calendar days after receipt of Invoice Alpha.'),False,'Trigger timestamp absent; no invented calendar deadline','REVIEW_REQUIRED')
    add('N19',sections(anchor,'Payment is required within 30 calendar days after receipt of Invoice Alpha.'),False,'Responsible actor not stated; do not invent actor','REVIEW_REQUIRED')
    add('N20',sections('The Effective Date is 03/04/2026.','The Expiration Date is 04/03/2026.'),False,'Numeric locale ambiguous; no unique ordering','REVIEW_REQUIRED')
    add('N21',sections('The Effective Date is February 30, 2026.'),False,'Calendar-invalid date must not silently disappear','REVIEW_REQUIRED')
    add('N22',sections('The archive entry dated December 31, 2026 relates to a historical entry dated January 1, 2026.'),False,'Historical independent dates are not an interval')
    add('N23',sections('The Expiration Date is 2026-07-01.','Buyer shall give notice at least 30 calendar days before the Expiration Date.'),False,'Notice period is a duration relative to expiry, not a competing expiry date')
    add('N24',sections('This agreement is executed on 2026-07-01.','The Expiration Date is 2026-06-01.','The parties expressly authorize retrospective ratification.'),None,'Execution/effectiveness/legal retroactivity not mechanically invalid',provisional=True)
    add('N25',sections('For the initial term, the Effective Date is 2026-01-01.','For the initial term, the Expiration Date is 2026-12-31.','For the renewal term, the Effective Date is 2027-01-01.','For the renewal term, the Expiration Date is 2027-12-31.'),False,'Initial and renewal phases individually ordered')
    add('N26',sections('Event Completion occurs on 2026-06-01.','If approval is granted, Event Completion occurs on 2026-07-01.'),False,'Conditional alternate date is not an unconditional singleton conflict')
    add('N27',sections('Event Completion occurs on approximately 2026-06-01.','Event Completion occurs on 2026-06-03.'),False,'Approximate dates do not imply disjoint exact singleton dates')
    add('N28',sections('Service runs from 2026-12-31 to 2026-01-01.'),True,'Explicit from-to range inverted')
    add('N29',sections('Review records list 2026-12-31 and 2026-01-01 independently.'),False,'Descending dates without range syntax are not inverted range')
    add('N30',sections('The Effective Date is 2026-06-01.','Payment due on 2026-05-01 is an expressly permitted refundable advance deposit.'),False,'Explicit permitted prepayment cannot be a confirmed conflict')
    add('N31',sections('Milestone Alpha occurs on 2026-06-02.','Milestone Beta occurs on 2026-06-01.','Milestone Alpha must occur before Milestone Beta.'),True,'Explicit ordered event sequence contradicted by stated exact dates')
    add('N32',sections('Milestone Alpha occurs on 2026-06-02.','Milestone Beta occurs on 2026-06-01.'),False,'No sequence constraint; section order is not temporal order')
    add('N33',sections('Milestone Alpha occurs on 2026-06-02.','Milestone Beta occurs on 2026-06-01.','Milestone Alpha need not occur before Milestone Beta.'),False,'Negated sequence is not positive before constraint')
    add('N34',sections(anchor,'Buyer shall pay Invoice Alpha exactly 2 weeks after receipt of Invoice Alpha.','Buyer shall pay Invoice Alpha exactly 14 calendar days after receipt of Invoice Alpha.'),False,'Two calendar weeks equal 14 calendar days')
    add('N35',sections(anchor,'Buyer shall pay Invoice Alpha within 1 month after receipt of Invoice Alpha.'),False,'Month boundary/calendar policy not defined for arithmetic','UNSUPPORTED')
    add('N36',sections('The Expiration Date is 2026-07-20.','Buyer shall give notice no later than 5 calendar days before the Expiration Date.','Buyer shall give notice on 2026-07-18.'),True,'Absolute notice date violates explicit latest July 15, not inferred from expiry alone')
    add('N37',sections(anchor,'Invoice Beta is received on 2026-01-15.',relative,'Buyer shall pay Invoice Alpha within 10 calendar days after receipt of Invoice Beta.'),False,'Different named invoice receipts remain distinct triggers')
    add('N38',sections('The Effective Date is\n2026-06-01.\nThe Expiration Date is\n2026-05-01.'),True,'Source roles survive line wrapping independently of neural segmentation')
    add('N39',sections('The Effective Date and the Expiration Date are 2026-06-01.'),False,'Multiple roles around one date need no invented conflicting endpoint')
    add('N40',sections('The Effective Date is 2026/01/01.','The Expiration Date is 2026/12/31.'),False,'Year-first slash dates have defined ordering')
    add('N41',sections('The Effective Date is 13/01/2026.','The Expiration Date is 01/02/2026.'),False,'Second date still ambiguous; do not force locale from first','REVIEW_REQUIRED')
    add('N42',sections('2026-12-31 is the Effective Date.','2026-01-01 is the Expiration Date.'),True,'Following role within full statement permits reversed endpoint check')
    add('N43',sections(anchor,'Buyer shall pay Invoice Alpha within thirty (30) calendar days after receipt of Invoice Alpha.','Buyer shall pay Invoice Alpha on 2026-02-15.'),True,'Written and numeric durations agree; Jan 31 upper bound')
    add('N44',sections(anchor,'Buyer shall pay Invoice Alpha within thirty (60) calendar days after receipt of Invoice Alpha.'),False,'Written/numeric duration disagreement requests review','REVIEW_REQUIRED')
    add('N45',sections('Event Completion occurs on 2026-06-01.','Event completion occurs on 2026-06-01.'),False,'Case folding alone is not a different event')
    add('N46',sections('Buyer shall complete Inspection on 2026-06-01.','Seller shall complete Inspection on 2026-07-01.'),False,'Different actors with same action are distinct obligations')
    add('N47',sections('For the initial term, Event Completion occurs on 2026-06-01.','For the renewal term, Event Completion occurs on 2027-06-01.'),False,'Same event label in distinct phases not conflated')
    add('N48',sections('The Expiration Date is 2026-07-20.','Buyer shall give notice at least 10 calendar days before the Expiration Date.','Buyer shall give notice no later than 5 calendar days before the Expiration Date.'),False,'Before-event upper bounds overlap')
    add('N49',sections('Service runs from May 10, 2026 through May 1, 2026.'),True,'Named-month explicit range inverted')
    add('N50',sections('The Effective Date is 2024-02-29.','The contract duration is 1 year from the Effective Date.'),False,'Anniversary/leap-year duration policy unsupported','UNSUPPORTED')
    add('N51',sections('Event Completion occurs on 2026-06-01 at 09:00 UTC.','Event Completion occurs on 2026-06-01 at 10:00 UTC.'),False,'Time-of-day semantics outside date-only engine','UNSUPPORTED')
    add('N52',sections('If renewed, Buyer shall give notice within 30 calendar days after Event Renewal Approval.'),False,'Conditional renewal trigger missing; no calendar anchor invented','REVIEW_REQUIRED')
    add('P01',sections('Buyer shall give notice within 10 business days.','Except in emergencies, Buyer shall give notice within 20 calendar days.'),None,'Exception scope and calendar require interpretation',provisional=True)
    add('P02',sections('Payment is due before effectiveness unless waived.'),None,'No absolute date or unique timing basis',provisional=True)
    add('P03',sections('Delivery should occur around the first week of May 2026.'),None,'Approximate natural-language window',provisional=True)
    add('P04',sections('The amended schedule supersedes the previous completion date.'),None,'No dated old/new facts; legal precedence not inferred',provisional=True)
    add('P05',sections('Notice is required promptly after material breach.'),None,'Qualitative duration and trigger interpretation',provisional=True)
    add('P06',sections('The parties may extend the term by mutual consent.'),None,'Possible future extension does not define actual expiry',provisional=True)
    payload=dict(dataset_role='NEWLY_AUTHORED_EXPOSED_SYNTHETIC_DEVELOPMENT',independent_adjudication_count=0,cases=cases)
    target.write_text(json.dumps(payload,indent=2)+'\n',encoding='utf8')
    (BASE/'new_cases.sha256').write_text(hashlib.sha256(target.read_bytes()).hexdigest()+'\n',encoding='utf8')
    print(len(cases),'new cases;',sum(c['provenance']=='NEW_MECHANICAL_SYNTHETIC' for c in cases),'mechanical;',sum(c['provenance']=='PROVISIONAL_INTERPRETATION' for c in cases),'provisional')
if __name__=='__main__':build()
